mapper.select:
SELECT code_stats.service_code_total, code_stats.service_code_waiting, code_stats.service_code_expiring, code_stats.service_code_expired, code_stats.service_code_processing, code_stats.service_code_consumed, account_stats.account_total, account_stats.account_waiting, account_stats.account_active, account_stats.account_expired, account_stats.account_disabled, generation_stats.generation_order_total, exchange_stats.exchange_total, renewal_stats.renewal_total, transfer_stats.transfer_total FROM ( SELECT COUNT(*) AS service_code_total, COALESCE(SUM(CASE WHEN sc.status = 'PENDING' AND sc.expire_at > #{upcomingAt} THEN 1 ELSE 0 END), 0) AS service_code_waiting, COALESCE(SUM(CASE WHEN sc.status = 'PENDING' AND sc.expire_at > #{now} AND sc.expire_at <= #{upcomingAt} THEN 1 ELSE 0 END), 0) AS service_code_expiring, COALESCE(SUM(CASE WHEN sc.status = 'PENDING' AND sc.expire_at <= #{now} THEN 1 ELSE 0 END), 0) AS service_code_expired, COALESCE(SUM(CASE WHEN sc.status = 'PROCESSING' THEN 1 ELSE 0 END), 0) AS service_code_processing, COALESCE(SUM(CASE WHEN sc.status = 'CONSUMED' THEN 1 ELSE 0 END), 0) AS service_code_consumed FROM service_code sc
sc.owner_company_id = #{scopeCompanyId}
) code_stats CROSS JOIN ( SELECT COUNT(*) AS account_total, COALESCE(SUM(CASE WHEN a.cors_status = 'ENABLED' AND a.cors_activation_status = 'WAITING_ACTIVATION' THEN 1 ELSE 0 END), 0) AS account_waiting, COALESCE(SUM(CASE WHEN a.cors_status = 'ENABLED' AND a.cors_activation_status = 'ACTIVE' THEN 1 ELSE 0 END), 0) AS account_active, COALESCE(SUM(CASE WHEN a.cors_status = 'ENABLED' AND a.cors_activation_status = 'EXPIRED' THEN 1 ELSE 0 END), 0) AS account_expired, COALESCE(SUM(CASE WHEN a.cors_status = 'DISABLED' THEN 1 ELSE 0 END), 0) AS account_disabled FROM service_account a
a.owner_company_id = #{scopeCompanyId}
AND a.assigned_user_id = #{scopeAssignedUserId}
) account_stats CROSS JOIN ( SELECT COUNT(*) AS generation_order_total FROM service_code_generate_order o
o.owner_company_id = #{scopeCompanyId}
) generation_stats CROSS JOIN ( SELECT COUNT(*) AS exchange_total FROM exchange_batch b
b.owner_company_id = #{scopeCompanyId}
) exchange_stats CROSS JOIN ( SELECT COUNT(*) AS renewal_total FROM account_renewal r
r.owner_company_id = #{scopeCompanyId}
AND r.assigned_user_id = #{scopeAssignedUserId}
) renewal_stats CROSS JOIN ( SELECT COUNT(DISTINCT t.transfer_no) AS transfer_total FROM service_code_transfer t
(t.from_company_id = #{scopeCompanyId} OR t.to_company_id = #{scopeCompanyId})
) transfer_stats
